def transform(grid):
    g = np.array(grid)
    bg = background(g)
    cols = [c for c in np.unique(g) if c != bg]
    out = g.copy()
    for cup in cols:
        for fill in cols:
            if fill == cup:
                continue
            n = int((g == fill).sum())
            for comp in components(g == cup, diagonal=True):
                interior = []
                rows = {}
                for y, x in comp:
                    rows.setdefault(y, []).append(x)
                for y, xs in rows.items():
                    for x in range(min(xs) + 1, max(xs)):
                        if g[y, x] == bg:
                            interior.append((y, x))
                if interior and len(interior) == n:
                    out[g == fill] = bg
                    emit(out, f"Remove the {n} loose colour-{fill} cells from their original spots.")
                    for y, x in interior:
                        out[y, x] = fill
                    emit(out, f"Pour them into the colour-{cup} cup whose interior holds exactly {n} cells.")
                    return out
    emit(out, "No matching cup; grid unchanged.")
    return out
